-- Explicitly reviewed, whole-event documentary links; no settlement is inferred.
CREATE TABLE trade_reconciliations_v2 (
 id TEXT PRIMARY KEY NOT NULL, trade_id TEXT NOT NULL REFERENCES share_trades(id),
 reviewed_trade TEXT NOT NULL CHECK(json_valid(reviewed_trade)),
 seller_events TEXT NOT NULL CHECK(json_valid(seller_events) AND json_type(seller_events)='array'),
 buyer_events TEXT NOT NULL CHECK(json_valid(buyer_events) AND json_type(buyer_events)='array'),
 reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 450), request_key TEXT NOT NULL UNIQUE,
 created_by TEXT NOT NULL REFERENCES "user"(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE trade_reconciliation_revocations_v2 (
 id TEXT PRIMARY KEY NOT NULL, link_id TEXT NOT NULL UNIQUE REFERENCES trade_reconciliations_v2(id),
 reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 450), request_key TEXT NOT NULL UNIQUE,
 created_by TEXT NOT NULL REFERENCES "user"(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER trade_reconciliation_v2_validate BEFORE INSERT ON trade_reconciliations_v2 BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') THEN RAISE(ABORT,'unauthorized') END;
 SELECT CASE WHEN json_array_length(NEW.seller_events) NOT BETWEEN 1 AND 100 OR json_array_length(NEW.buyer_events)>100 THEN RAISE(ABORT,'invalid event count') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM share_trades t JOIN share_sale_requests s ON s.id=t.sale_id JOIN members sm ON sm.id=s.member_id LEFT JOIN members bm ON bm.id=t.buyer_member_id WHERE t.id=NEW.trade_id AND NOT EXISTS(SELECT 1 FROM share_trade_voids v WHERE v.trade_id=t.id)
 AND json_extract(NEW.reviewed_trade,'$.id')=t.id AND json_extract(NEW.reviewed_trade,'$.sellerId')=sm.id AND json_extract(NEW.reviewed_trade,'$.sellerName')=sm.full_name AND json_extract(NEW.reviewed_trade,'$.sellerNumber')=sm.member_number AND json_extract(NEW.reviewed_trade,'$.buyerType')=t.buyer_type AND json_extract(NEW.reviewed_trade,'$.buyerId') IS t.buyer_member_id AND json_extract(NEW.reviewed_trade,'$.buyerName') IS bm.full_name AND json_extract(NEW.reviewed_trade,'$.buyerNumber') IS bm.member_number AND json_extract(NEW.reviewed_trade,'$.tradeDate')=t.trade_date AND json_extract(NEW.reviewed_trade,'$.shares')=t.shares AND json_extract(NEW.reviewed_trade,'$.currency')=t.currency AND json_extract(NEW.reviewed_trade,'$.priceMinor')=t.price_minor AND json_extract(NEW.reviewed_trade,'$.considerationMinor')=t.consideration_minor AND json_extract(NEW.reviewed_trade,'$.reference') IS t.reference
 AND ((t.buyer_type='group' AND json_array_length(NEW.buyer_events)=0) OR (t.buyer_type='member' AND json_array_length(NEW.buyer_events)>0))) THEN RAISE(ABORT,'trade changed or does not match; review again') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM (SELECT value, 'sale' side FROM json_each(NEW.seller_events) UNION ALL SELECT value, 'purchase' side FROM json_each(NEW.buyer_events)) x WHERE NOT EXISTS(SELECT 1 FROM share_events e JOIN members m ON m.id=e.member_id JOIN share_trades t ON t.id=NEW.trade_id JOIN share_sale_requests s ON s.id=t.sale_id WHERE e.id=json_extract(x.value,'$.id') AND e.member_id=CASE x.side WHEN 'sale' THEN s.member_id ELSE t.buyer_member_id END AND e.event_type=x.side AND e.shares BETWEEN 1 AND 9007199254740991 AND NOT EXISTS(SELECT 1 FROM share_event_voids v WHERE v.event_id=e.id)
 AND json_extract(x.value,'$.memberId')=e.member_id AND json_extract(x.value,'$.memberName')=m.full_name AND json_extract(x.value,'$.memberNumber')=m.member_number AND json_extract(x.value,'$.eventType')=e.event_type AND json_extract(x.value,'$.eventDate')=e.event_date AND json_extract(x.value,'$.shares')=e.shares AND json_extract(x.value,'$.reference') IS e.reference)) THEN RAISE(ABORT,'events changed or do not match; review again') END;
 SELECT CASE WHEN (SELECT count(*) FROM (SELECT json_extract(value,'$.id') id FROM json_each(NEW.seller_events) UNION ALL SELECT json_extract(value,'$.id') FROM json_each(NEW.buyer_events))) != (SELECT count(DISTINCT id) FROM (SELECT json_extract(value,'$.id') id FROM json_each(NEW.seller_events) UNION ALL SELECT json_extract(value,'$.id') FROM json_each(NEW.buyer_events))) THEN RAISE(ABORT,'duplicate events') END;
 SELECT CASE WHEN (SELECT sum(json_extract(value,'$.shares')) FROM json_each(NEW.seller_events)) != (SELECT shares FROM share_trades WHERE id=NEW.trade_id) OR (json_array_length(NEW.buyer_events)>0 AND (SELECT sum(json_extract(value,'$.shares')) FROM json_each(NEW.buyer_events)) != (SELECT shares FROM share_trades WHERE id=NEW.trade_id)) THEN RAISE(ABORT,'event quantities do not match trade') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM trade_reconciliations l WHERE NOT EXISTS(SELECT 1 FROM trade_reconciliation_revocations r WHERE r.link_id=l.id) AND (l.trade_id=NEW.trade_id OR l.seller_event_id IN (SELECT json_extract(value,'$.id') FROM json_each(NEW.seller_events) UNION ALL SELECT json_extract(value,'$.id') FROM json_each(NEW.buyer_events)) OR l.buyer_event_id IN (SELECT json_extract(value,'$.id') FROM json_each(NEW.seller_events) UNION ALL SELECT json_extract(value,'$.id') FROM json_each(NEW.buyer_events)))) OR EXISTS(SELECT 1 FROM trade_reconciliations_v2 l WHERE NOT EXISTS(SELECT 1 FROM trade_reconciliation_revocations_v2 r WHERE r.link_id=l.id) AND (l.trade_id=NEW.trade_id OR EXISTS(SELECT 1 FROM (SELECT json_extract(value,'$.id') id FROM json_each(l.seller_events) UNION ALL SELECT json_extract(value,'$.id') FROM json_each(l.buyer_events)) old WHERE old.id IN (SELECT json_extract(value,'$.id') FROM json_each(NEW.seller_events) UNION ALL SELECT json_extract(value,'$.id') FROM json_each(NEW.buyer_events))))) THEN RAISE(ABORT,'trade or share event already linked') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM trade_reconciliations WHERE request_key=NEW.request_key) THEN RAISE(ABORT,'request key already used') END;
END;
CREATE TRIGGER trade_reconciliation_legacy_v2_guard BEFORE INSERT ON trade_reconciliations WHEN EXISTS(SELECT 1 FROM trade_reconciliations_v2 l WHERE l.request_key=NEW.request_key OR (NOT EXISTS(SELECT 1 FROM trade_reconciliation_revocations_v2 r WHERE r.link_id=l.id) AND (l.trade_id=NEW.trade_id OR EXISTS(SELECT 1 FROM (SELECT json_extract(value,'$.id') id FROM json_each(l.seller_events) UNION ALL SELECT json_extract(value,'$.id') FROM json_each(l.buyer_events)) e WHERE e.id IN (NEW.seller_event_id,NEW.buyer_event_id))))) BEGIN SELECT RAISE(ABORT,'trade or share event already linked'); END;
CREATE TRIGGER trade_reconciliation_v2_revoke_validate BEFORE INSERT ON trade_reconciliation_revocations_v2 BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') THEN RAISE(ABORT,'unauthorized') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM trade_reconciliation_revocations WHERE request_key=NEW.request_key) THEN RAISE(ABORT,'request key already used') END;
END;
CREATE TRIGGER trade_reconciliation_legacy_revoke_v2_guard BEFORE INSERT ON trade_reconciliation_revocations WHEN EXISTS(SELECT 1 FROM trade_reconciliation_revocations_v2 WHERE request_key=NEW.request_key) BEGIN SELECT RAISE(ABORT,'request key already used'); END;
CREATE TRIGGER trade_reconciliation_v2_no_update BEFORE UPDATE ON trade_reconciliations_v2 BEGIN SELECT RAISE(ABORT,'reconciliation history immutable'); END;
CREATE TRIGGER trade_reconciliation_v2_no_delete BEFORE DELETE ON trade_reconciliations_v2 BEGIN SELECT RAISE(ABORT,'reconciliation history immutable'); END;
CREATE TRIGGER trade_reconciliation_v2_revoke_no_update BEFORE UPDATE ON trade_reconciliation_revocations_v2 BEGIN SELECT RAISE(ABORT,'reconciliation history immutable'); END;
CREATE TRIGGER trade_reconciliation_v2_revoke_no_delete BEFORE DELETE ON trade_reconciliation_revocations_v2 BEGIN SELECT RAISE(ABORT,'reconciliation history immutable'); END;
CREATE TRIGGER trade_reconciliation_v2_trade_void BEFORE INSERT ON share_trade_voids WHEN EXISTS(SELECT 1 FROM trade_reconciliations_v2 l WHERE l.trade_id=NEW.trade_id AND NOT EXISTS(SELECT 1 FROM trade_reconciliation_revocations_v2 r WHERE r.link_id=l.id)) BEGIN SELECT RAISE(ABORT,'revoke trade reconciliation before void'); END;
CREATE TRIGGER trade_reconciliation_v2_event_void BEFORE INSERT ON share_event_voids WHEN EXISTS(SELECT 1 FROM trade_reconciliations_v2 l WHERE NOT EXISTS(SELECT 1 FROM trade_reconciliation_revocations_v2 r WHERE r.link_id=l.id) AND EXISTS(SELECT 1 FROM (SELECT json_extract(value,'$.id') id FROM json_each(l.seller_events) UNION ALL SELECT json_extract(value,'$.id') FROM json_each(l.buyer_events)) e WHERE e.id=NEW.event_id)) BEGIN SELECT RAISE(ABORT,'revoke trade reconciliation before void event'); END;
CREATE TRIGGER trade_reconciliation_v2_event_update BEFORE UPDATE ON share_events WHEN EXISTS(SELECT 1 FROM trade_reconciliations_v2 l WHERE NOT EXISTS(SELECT 1 FROM trade_reconciliation_revocations_v2 r WHERE r.link_id=l.id) AND EXISTS(SELECT 1 FROM (SELECT json_extract(value,'$.id') id FROM json_each(l.seller_events) UNION ALL SELECT json_extract(value,'$.id') FROM json_each(l.buyer_events)) e WHERE e.id=OLD.id)) BEGIN SELECT RAISE(ABORT,'revoke trade reconciliation before changing event'); END;
CREATE TRIGGER trade_reconciliation_v2_event_delete BEFORE DELETE ON share_events WHEN EXISTS(SELECT 1 FROM trade_reconciliations_v2 l WHERE NOT EXISTS(SELECT 1 FROM trade_reconciliation_revocations_v2 r WHERE r.link_id=l.id) AND EXISTS(SELECT 1 FROM (SELECT json_extract(value,'$.id') id FROM json_each(l.seller_events) UNION ALL SELECT json_extract(value,'$.id') FROM json_each(l.buyer_events)) e WHERE e.id=OLD.id)) BEGIN SELECT RAISE(ABORT,'revoke trade reconciliation before deleting event'); END;
